import json, sys

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def summarize_content(content):
    out = []
    if isinstance(content, str):
        out.append(("text", trunc(content, 500)))
        return out
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                out.append(("?", trunc(block)))
                continue
            btype = block.get("type")
            if btype == "text":
                out.append(("text", trunc(block.get("text",""), 500)))
            elif btype == "tool_use":
                out.append(("tool_use", block.get("name"), trunc(json.dumps(block.get("input",{})), 300)))
            elif btype == "tool_result":
                c = block.get("content")
                if isinstance(c, list):
                    ctext = " ".join(trunc(b.get("text",""),200) for b in c if isinstance(b,dict))
                else:
                    ctext = trunc(c, 300)
                out.append(("tool_result", "ERR" if block.get("is_error") else "ok", ctext))
            else:
                out.append((btype, trunc(block)))
    return out

fname = sys.argv[1]
with open(fname) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        t = d.get("type")
        ts = d.get("timestamp", "")
        if t in ("user", "assistant"):
            msg = d.get("message", {})
            role = msg.get("role", t)
            content = msg.get("content")
            summ = summarize_content(content)
            print(f"[{i}] {ts} {role}:")
            for s in summ:
                print("   ", s)
        elif t == "queue-operation":
            print(f"[{i}] {ts} QUEUE {d.get('operation')}: {trunc(d.get('content',''),200)}")
        elif t == "attachment":
            att = d.get("attachment", {})
            print(f"[{i}] {ts} ATTACHMENT {att.get('type')}: {trunc(att.get('content', att.get('stdout','')),300)}")
        elif t == "last-prompt":
            print(f"[{i}] {ts} LAST-PROMPT")
        elif t == "atis-latch":
            print(f"[{i}] {ts} ATIS-LATCH")
        else:
            print(f"[{i}] {ts} {t} {trunc(d,150)}")

