import json, sys

def trunc(s, n=300):
    s = s.replace("\n", " ")
    return s[:n] + ("..." if len(s) > n else "")

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get("type")
            ts = d.get("timestamp", "")
            if t == "queue-operation":
                print(f"[{ts}] QUEUE-{d.get('operation')}: {trunc(d.get('content',''), 400)}")
            elif t == "user":
                msg = d.get("message", {})
                content = msg.get("content")
                if isinstance(content, str):
                    print(f"[{ts}] USER: {trunc(content, 400)}")
                elif isinstance(content, list):
                    for c in content:
                        if c.get("type") == "text":
                            print(f"[{ts}] USER: {trunc(c.get('text',''), 400)}")
                        elif c.get("type") == "tool_result":
                            cc = c.get("content")
                            if isinstance(cc, list):
                                for cc2 in cc:
                                    if cc2.get("type") == "text":
                                        print(f"[{ts}] TOOL_RESULT: {trunc(cc2.get('text',''), 200)}")
                            elif isinstance(cc, str):
                                print(f"[{ts}] TOOL_RESULT: {trunc(cc, 200)}")
            elif t == "assistant":
                msg = d.get("message", {})
                content = msg.get("content", [])
                for c in content:
                    if c.get("type") == "text":
                        print(f"[{ts}] ASSISTANT: {trunc(c.get('text',''), 400)}")
                    elif c.get("type") == "tool_use":
                        name = c.get("name")
                        inp = json.dumps(c.get("input", {}))
                        print(f"[{ts}] TOOL_USE {name}: {trunc(inp, 200)}")
            elif t == "attachment":
                att = d.get("attachment", {})
                hn = att.get("hookName") or att.get("type")
                print(f"[{ts}] ATTACHMENT {hn}")
            elif t == "system":
                print(f"[{ts}] SYSTEM: {trunc(str(d.get('content',''))[:200], 200)}")

if __name__ == "__main__":
    main(sys.argv[1])

